import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 单元 1 复习与自测 · 第1–11课","description":"L1–L20 原创练习和答案解析。","frontmatter":{"title":"第三册：培养技能 · 单元 1 复习与自测 · 第1–11课","description":"L1–L20 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-3/unit-01/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 1 复习与自测","summary":"L1–L20 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 1 复习与自测","link":"/life/english/new-concept/book-3/unit-01/review"},"next":{"text":"第三册：培养技能 · 单元 1 复习与自测 · 第12–20课","link":"/life/english/new-concept/book-3/unit-01/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 1 复习与自测","link":"/life/english/new-concept/book-3/unit-01/review"},"next":{"text":"第三册：培养技能 · 单元 1 复习与自测 · 第12–20课","link":"/life/english/new-concept/book-3/unit-01/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/review-part-01.md","filePath":"life/english/new-concept/book-3/unit-01/review-part-01.md"}'),n={name:"life/english/new-concept/book-3/unit-01/review-part-01.md"};function r(l,e,i,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-单元-1-复习与自测-·-第1–11课" tabindex="-1">第三册：培养技能 · 单元 1 复习与自测 · 第1–11课 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-复习与自测-·-第1–11课" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1 复习与自测 · 第1–11课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-01/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第三册-培养技能-·-单元-1-复习与自测" tabindex="-1">第三册：培养技能 · 单元 1 复习与自测 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-复习与自测" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1 复习与自测 {#第三册-培养技能-·-单元-1-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-1-·-定语从句与证据限定" tabindex="-1">Lesson 1 · 定语从句与证据限定 <a class="header-anchor" href="#lesson-1-·-定语从句与证据限定" aria-label="Permalink to &quot;Lesson 1 · 定语从句与证据限定 {#lesson-1-·-定语从句与证据限定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The tracks that we found near the gate may belong to a large dog.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>把例句中的 that 省略，句子还成立吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 成立。</p><p><strong>解析：</strong> that 在关系从句中作 found 的宾语。</p></details><p><strong>表达迁移：</strong> 用三句英语写一次尚未证实的校园动物目击报告，必须区分证据和推测。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A student noticed fresh tracks behind the library. The camera that faces the garden recorded a shadow. It may have been a fox, but we need clearer evidence.</p><p>noticed 和 recorded 报告观察结果；may 和 but 给结论保留边界。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-001">回看本课</a></p><h2 id="lesson-2-·-过去进行时与突发事件" tabindex="-1">Lesson 2 · 过去进行时与突发事件 <a class="header-anchor" href="#lesson-2-·-过去进行时与突发事件" aria-label="Permalink to &quot;Lesson 2 · 过去进行时与突发事件 {#lesson-2-·-过去进行时与突发事件}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was checking the clock when a loose screw fell onto the floor.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>填空：We ___ dinner when the bell rang.（were having/had had）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were having</p><p><strong>解析：</strong> 本题强调铃响时正在吃饭。</p></details><p><strong>表达迁移：</strong> 写三句维修中的意外，先给持续背景，再给突发事件，最后给结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Nora was cleaning an old alarm clock. A tiny spring suddenly flew across the desk. She found it inside an empty cup.</p><p>进行时设置场景，两个一般过去时动词按顺序推进故事。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-002">回看本课</a></p><h2 id="lesson-3-·-过去完成时的时间参照" tabindex="-1">Lesson 3 · 过去完成时的时间参照 <a class="header-anchor" href="#lesson-3-·-过去完成时的时间参照" aria-label="Permalink to &quot;Lesson 3 · 过去完成时的时间参照 {#lesson-3-·-过去完成时的时间参照}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time the team reached the chamber, water had damaged several paintings.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>例句中先发生的是到达还是损坏？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 损坏。</p><p><strong>解析：</strong> had damaged 位于 reached 之前。</p></details><p><strong>表达迁移：</strong> 用三句介绍一个虚构发现，清楚标出发现前的损坏与现在的保管安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Researchers uncovered a painted bowl last month. Soil pressure had cracked its base before they arrived. The museum now keeps the fragments in a protective case.</p><p>过去时报告发现，过去完成时回溯损坏，现在时描述当前保存状态。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-003">回看本课</a></p><h2 id="lesson-4-·-used-to-与过去习惯" tabindex="-1">Lesson 4 · used to 与过去习惯 <a class="header-anchor" href="#lesson-4-·-used-to-与过去习惯" aria-label="Permalink to &quot;Lesson 4 · used to 与过去习惯 {#lesson-4-·-used-to-与过去习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Leo used to hide his work clothes, but now he talks openly about his job.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>把例句的 hide 改成否定过去习惯。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Leo didn&#39;t use to hide his work clothes.</p><p><strong>解析：</strong> didn&#39;t 后 use 保持原形。</p></details><p><strong>表达迁移：</strong> 描述一个人对职业看法的变化，包含过去习惯、转折原因和现在的态度。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mia used to avoid questions about her cleaning job. A grateful customer changed her view of the work. She now introduces herself with confidence.</p><p>用具体事件解释态度变化，避免只贴性格标签。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-004">回看本课</a></p><h2 id="lesson-5-·-间接疑问句的陈述语序" tabindex="-1">Lesson 5 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-5-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 5 · 间接疑问句的陈述语序 {#lesson-5-·-间接疑问句的陈述语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The editor asked how many households the survey had covered.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>改写：She asked, “Is the figure final?”</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She asked whether the figure was final.</p><p><strong>解析：</strong> 一般疑问转述用 whether，语序为主语加谓语。</p></details><p><strong>表达迁移：</strong> 写一段核实活动人数的编辑记录，包含一个间接疑问句和一次更正。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I asked whether the total included volunteers. The organizer said that it did. We changed the headline to distinguish guests from staff.</p><p>whether 引出核实问题；最后一句说明核实如何影响报道。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-005">回看本课</a></p><h2 id="lesson-6-·-一般过去时的被动语态" tabindex="-1">Lesson 6 · 一般过去时的被动语态 <a class="header-anchor" href="#lesson-6-·-一般过去时的被动语态" aria-label="Permalink to &quot;Lesson 6 · 一般过去时的被动语态 {#lesson-6-·-一般过去时的被动语态}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Two display cases were damaged before the alarm was raised.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>把 Someone broke the glass 改为被动，省略行为人。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The glass was broken.</p><p><strong>解析：</strong> glass 作主语，break 的过去分词为 broken。</p></details><p><strong>表达迁移：</strong> 写三句虚构店铺事件记录，只陈述观察到的事实，不猜测嫌疑人身份。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A loud crash was heard at noon. One cabinet was found open near the entrance. Staff checked the camera recordings later that day.</p><p>前两句聚焦所听所见，末句主动说明工作人员的后续行动。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-006">回看本课</a></p><h2 id="lesson-7-·-可数与不可数名词" tabindex="-1">Lesson 7 · 可数与不可数名词 <a class="header-anchor" href="#lesson-7-·-可数与不可数名词" aria-label="Permalink to &quot;Lesson 7 · 可数与不可数名词 {#lesson-7-·-可数与不可数名词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Several fragments were missing, but most of the printed number was still visible.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>选择：There was ___ damage.（much/many）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> damage 表示损坏时通常不可数。</p></details><p><strong>表达迁移：</strong> 为受损物品写三句检查记录，交代数量、损坏和可识别特征。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We received four torn tickets. One ticket had lost its upper corner. The date remained clear on all four.</p><p>four 与 all four 准确对应，单数 ticket 的局部损坏没有被夸大成全部无法识别。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-007">回看本课</a></p><h2 id="lesson-8-·-地点介词与移动路径" tabindex="-1">Lesson 8 · 地点介词与移动路径 <a class="header-anchor" href="#lesson-8-·-地点介词与移动路径" aria-label="Permalink to &quot;Lesson 8 · 地点介词与移动路径 {#lesson-8-·-地点介词与移动路径}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A narrow path runs through the forest and ends at the old gate.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>填空：We walked ___ the bridge from one bank to the other.（across/inside）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> across</p><p><strong>解析：</strong> 明确从桥一端到另一端。</p></details><p><strong>表达迁移：</strong> 用三句为第一次来访的人描述山中图书馆的位置和路线。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The library stands above a small lake. A stone path leads through the pine trees. Visitors leave their cars at the lower gate and walk uphill.</p><p>三个地点短语依次建立位置、路径和起点，读者可以据此形成路线图。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-008">回看本课</a></p><h2 id="lesson-9-·-比较级与比较对象一致" tabindex="-1">Lesson 9 · 比较级与比较对象一致 <a class="header-anchor" href="#lesson-9-·-比较级与比较对象一致" aria-label="Permalink to &quot;Lesson 9 · 比较级与比较对象一致 {#lesson-9-·-比较级与比较对象一致}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The second ramp was slightly steeper than the first, so the cart moved faster.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填空：This surface is ___ smoother.（much/very）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> much 可以修饰比较级。</p></details><p><strong>表达迁移：</strong> 写三句比较两次纸飞机测试，说明条件与结果，不把单次结果说成定律。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The blue plane travelled farther than the red one in our first test. Its wings were also wider. We need more trials before drawing a conclusion.</p><p>用 in our first test 限定范围，最后一句明确证据不足。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-009">回看本课</a></p><h2 id="lesson-10-·-过去反事实条件句" tabindex="-1">Lesson 10 · 过去反事实条件句 <a class="header-anchor" href="#lesson-10-·-过去反事实条件句" aria-label="Permalink to &quot;Lesson 10 · 过去反事实条件句 {#lesson-10-·-过去反事实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the crew had received the warning earlier, they might have changed course.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>例句断言改变航向一定能发生吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> might 表示不确定的可能结果。</p></details><p><strong>表达迁移：</strong> 为一次虚构划船延误写三句回顾，包含事实、假设和改进。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We noticed the damaged oar after departure. If we had checked it at the dock, we could have replaced it. Next time, we will inspect all the equipment first.</p><p>过去事实与反事实分句分开，最后一句给出未来可执行的改进。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-010">回看本课</a></p><h2 id="lesson-11-·-转述要求与否定命令" tabindex="-1">Lesson 11 · 转述要求与否定命令 <a class="header-anchor" href="#lesson-11-·-转述要求与否定命令" aria-label="Permalink to &quot;Lesson 11 · 转述要求与否定命令 {#lesson-11-·-转述要求与否定命令}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The officer asked me to place the sealed box on the counter.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>转述：She said to us, “Do not move the bags.”</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She told us not to move the bags.</p><p><strong>解析：</strong> 否定命令用 not to do。</p></details><p><strong>表达迁移：</strong> 用三句描述一次包裹检查，包含一个要求和一个解释。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The clerk asked me to open the outer carton. I explained that the glass bowls were gifts. She checked the label and thanked me for waiting.</p><p>要求用 to open，解释用 that 从句，两种转述结构作用不同。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-011">回看本课</a></p>',95)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
